insert into requirement_packs (jurisdiction_code, version, requirements)
values ('CA', 1, '[{"key":"application","label":"Rental Application","description":"A completed rental application form with the applicant''s name, contact information, current address, and employment details.\n","keywords":["application","rental application","applicant form","tenant application"]},{"key":"government_id","label":"Government-Issued ID","description":"A copy of a government-issued photo ID such as a driver''s license, state ID card, or passport, used to verify the applicant''s identity.\n","keywords":["id","identification","driver''s license","drivers license","state id","passport"]},{"key":"income_proof","label":"Proof of Income","description":"Documentation showing the applicant''s income, such as recent pay stubs, an offer letter, bank statements, or a tax return.\n","keywords":["pay stub","paystub","proof of income","income statement","offer letter","bank statement","w-2","tax return"]},{"key":"background_check_consent","label":"Background Check Consent","description":"A signed authorization allowing the landlord or their screening provider to run a background and credit check on the applicant.\n","keywords":["background check","consent","authorization","credit check consent","screening consent"]},{"key":"prior_landlord_contact","label":"Prior Landlord Contact","description":"Contact information for the applicant''s current or most recent landlord, used as a rental history reference.\n","keywords":["prior landlord","previous landlord","current landlord","landlord reference","rental reference"]}]'::jsonb)
